urlset:
{{ $pages := union (where site.RegularPages "Type" "posts") (where site.RegularPages "Type" "posts") }}
{{ range site.Home.AllTranslations }}

  {{ .Permalink }}
  {{ if .IsTranslated }}{{ range .Translations }}

  {{ end }}{{ end }}

{{ end }}
{{ range where site.AllPages "Kind" "page" }}
{{ if in .Permalink "/posts/" }}

  {{ .Permalink }}
  {{ .Date.Format "2006-01-02T15:04:05Z07:00" }}
  {{ range .AllTranslations }}

  {{ end }}

{{ end }}
{{ end }}
{{ range where site.AllPages "Kind" "section" }}
{{ if or (eq .Permalink (absURL "archives/")) (eq .Permalink (absURL "about/")) (eq .Permalink (absURL "privacy/")) }}
{{ .Permalink }}
{{ end }}
{{ end }}
